function tryParseJSON(x) {
  if (typeof x !== 'string') return x;
  try { return JSON.parse(x); } catch (e) { return null; }
}

function esc(value) {
  return String(value ?? "").replace(/[&<>"']/g, c => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;",
    '"': "&quot;", "'": "&#39;"
  }[c]));
}

let checkFailed = false;
let failureReason = "";
let campaign, aiReview, codeResults, ruleTable, combinedResults = [];
let mode = "initial";
let eventCheckResults = [];
let eventUpdateInfo = null;
let currentEventDate = "", currentEventTime = "", currentEventTimezone = "";

try {
  const cd = $('Campaign Data').first().json;
  const webhookBody = ($('Webhook').first().json && $('Webhook').first().json.body) || {};
  mode = webhookBody.mode === 'recheck' ? 'recheck'
       : webhookBody.mode === 'event_update' ? 'event_update'
       : 'initial';

  const sourcesJson = $('Sources').first().json;
  currentEventDate = sourcesJson.event_date || "";
  currentEventTime = sourcesJson.event_time || "";
  currentEventTimezone = sourcesJson.event_timezone || "";

  campaign = {
    email: { headline: cd.email_headline, body: cd.email_body, cta: cd.email_cta },
    landing_page: { headline: cd.landing_headline, body: cd.landing_body, cta: cd.landing_cta },
    creative_rationale: cd.creative_rationale,
    instruction_response: cd.instruction_response
  };

const mlrRaw = $("AI Consensus").first().json;
  aiReview = tryParseJSON(mlrRaw.output ?? mlrRaw.text ?? mlrRaw);
  codeResults = $("Code Checks").first().json.code_check_results;
  eventCheckResults = $("Code Checks").first().json.event_check_results || [];
  ruleTable = tryParseJSON($("Sources").first().json.rule_table);

  if (mode === 'event_update') {
    eventUpdateInfo = {
      old_date: currentEventDate,
      old_time: currentEventTime,
      new_date: webhookBody.new_event_date || currentEventDate,
      new_time: webhookBody.new_event_time || currentEventTime,
      timezone: currentEventTimezone
    };
  }

  function validAsset(asset) {
    return asset && ["headline", "body", "cta"].every(
      key => typeof asset[key] === "string" && asset[key].trim()
    );
  }

  if (!validAsset(campaign.email) || !validAsset(campaign.landing_page)) {
    throw new Error("Incomplete campaign draft output.");
  }
  if (!aiReview || !Array.isArray(aiReview.rule_results)) {
    throw new Error("Incomplete or invalid AI review output.");
  }
  if (!Array.isArray(codeResults)) {
    throw new Error("Incomplete code check output.");
  }
  if (!Array.isArray(ruleTable)) {
    throw new Error("Missing rule table.");
  }

  const allowedStatuses = new Set(["issues_flagged", "no_issue_detected", "not_assessable"]);
  for (const r of [...aiReview.rule_results, ...codeResults]) {
    if (!r || !allowedStatuses.has(r.status)) {
      throw new Error(`Invalid status for rule ${r && r.rule_id}.`);
    }
  }

  const codeById = {};
  for (const r of codeResults) { codeById[r.rule_id] = r; }
  const aiById = {};
  for (const r of aiReview.rule_results) { aiById[r.rule_id] = r; }

  combinedResults = ruleTable.map(rule => {
    const result = (rule.check_method === 'code' ? codeById[rule.rule_id] : aiById[rule.rule_id]) || {};
    return {
      rule_id: rule.rule_id,
      requirement: rule.requirement,
      check_method: rule.check_method,
      source_ref: rule.source_ref,
      ...result
    };
  });

} catch (err) {
  checkFailed = true;
  failureReason = err.message;
}

function statusLabel(status) {
  if (status === "issues_flagged") return "Issues flagged";
  if (status === "no_issue_detected") return "No issue detected in supplied material";
  if (status === "not_assessable") return "Not assessable from supplied material";
  return status || "Unknown";
}

function sourceLine(r) {
  const excerpt = (r.source_excerpt || "").trim();
  const ref = r.source_reference || r.source_ref || "the supplied sources";
  if (!excerpt || excerpt.toUpperCase() === "N/A") {
    return `No supporting statement found in supplied sources ${esc(ref)}.`;
  }
  return `${esc(ref)} &mdash; &ldquo;${esc(excerpt)}&rdquo;`;
}

function exceptionCard(r) {
  return `
    <li style="margin-bottom:16px;">
      <strong>${esc(r.rule_id)} &middot; ${esc(r.asset)}</strong> &mdash; ${esc(statusLabel(r.status))}<br>
      <em>Requirement:</em> ${esc(r.requirement)}<br>
      <em>Wording:</em> ${esc(r.wording)}<br>
      <em>Explanation:</em> ${esc(r.explanation)}<br>
      <em>Source:</em> ${sourceLine(r)}<br>
      <em>Suggested correction:</em> ${esc(r.suggested_correction)}<br>
      <em>Required human action:</em> ${esc(r.human_review_action)}
    </li>
  `;
}

function rowStyle(status) {
  if (status === "issues_flagged") return "background:#fdecea; color:#7a1f1f;";
  if (status === "not_assessable") return "background:#fff8e1; color:#7a5f00;";
  return "";
}

function evidenceRow(r) {
  const style = rowStyle(r.status);
  return `
    <tr style="${style}">
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(r.rule_id)}</td>
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(r.requirement)}</td>
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(r.check_method)}</td>
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(statusLabel(r.status))}</td>
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(r.asset)}</td>
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(r.source_reference || r.source_ref)}</td>
    </tr>
  `;
}

function eventCheckRow(r) {
  const style = rowStyle(r.status);
  return `
    <tr style="${style}">
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(r.rule_id)}</td>
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(r.explanation)}</td>
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(statusLabel(r.status))}</td>
      <td style="padding:6px; border:1px solid #E2E8EF;">${esc(r.human_review_action)}</td>
    </tr>
  `;
}

let html;

if (checkFailed) {
  const failureHeading = mode === 'event_update' ? 'Update check failed &mdash; retry required' : 'Check failed &mdash; retry required';
  const failureBody = mode === 'event_update'
    ? 'The automated event-detail update could not be completed due to a technical error. No new draft has been produced &mdash; any previously checked version remains the current result.'
    : 'The automated check could not complete due to a technical error. This is a technical failure, not a review result &mdash; no content has been assessed.';
  html = `
    <div style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 760px; margin: 0 auto; color: #243746; background: #F4F7FA; padding: 32px;">
      <div style="background:#14283F; color:#fff; padding:24px 32px; border-radius:8px 8px 0 0;">
        <div style="font-size:12px; letter-spacing:1px; opacity:0.75;">VERIDIAN LIFE SCIENCES &middot; VERIDIAN CAMPAIGN STUDIO</div>
        <h1 style="margin:8px 0 0; font-size:24px;">Campaign Sprint</h1>
      </div>
      <div style="background:#fff; padding:32px; border-radius:0 0 8px 8px; border:1px solid #E2E8EF; border-top:none;">
        <h2 style="color:#A86408;">${failureHeading}</h2>
        <p>${failureBody}</p>
        <p style="font-size:13px; color:#5b6b76;">Technical detail: ${esc(failureReason)}</p>
        <p>Please retry the submission. If this keeps happening, contact support.</p>
      </div>
    </div>
  `;
} else {
  if (mode === 'event_update' && eventUpdateInfo) {
    const staticData = $getWorkflowStaticData('global');
    staticData.eventDate = eventUpdateInfo.new_date;
    staticData.eventTime = eventUpdateInfo.new_time;
  }

  const eventSummaryHtml = eventUpdateInfo ? `
    <div style="background:#F2F8FB; border:1px solid #d3e3ec; border-radius:8px; padding:16px 20px; margin-bottom:20px; font-size:13px;">
      <strong style="color:#14283F;">Event details updated</strong><br>
      Date: ${esc(eventUpdateInfo.old_date)} &rarr; ${esc(eventUpdateInfo.new_date)}<br>
      Time: ${esc(eventUpdateInfo.old_time)} ${esc(eventUpdateInfo.timezone)} &rarr; ${esc(eventUpdateInfo.new_time)} ${esc(eventUpdateInfo.timezone)}
    </div>
    <h2 style="color:#087F8C;">Event update checks</h2>
    <table style="width:100%; border-collapse:collapse; font-size:13px; margin-bottom:20px;">
      <thead>
        <tr style="background:#F2F8FB;">
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Check</th>
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Detail</th>
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Status</th>
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Required human action</th>
        </tr>
      </thead>
      <tbody>${eventCheckResults.map(eventCheckRow).join("")}</tbody>
    </table>
  ` : '';

  const exceptions = combinedResults.filter(r => r.status !== "no_issue_detected");
  const exceptionsHtml = exceptions.length
    ? `<ul style="padding-left:18px;">${exceptions.map(exceptionCard).join("")}</ul>`
    : `<p>No exceptions &mdash; all checks completed with no issues detected in the supplied material.</p>`;

  const evidenceHtml = `
    <table style="width:100%; border-collapse:collapse; font-size:13px;">
      <thead>
        <tr style="background:#F2F8FB;">
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Rule</th>
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Requirement</th>
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Method</th>
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Status</th>
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Asset</th>
          <th style="padding:6px; border:1px solid #E2E8EF; text-align:left;">Source</th>
        </tr>
      </thead>
      <tbody>${combinedResults.map(evidenceRow).join("")}</tbody>
    </table>
  `;

  const resultData = JSON.stringify({ mode, campaign, rule_results: combinedResults });

  html = `
    <div id="campaignSprintReport" style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 760px; margin: 0 auto; color: #243746; background: #F4F7FA; padding: 32px;">
      <script type="application/json" id="resultData">${resultData}<\/script>
      <div style="background:#14283F; color:#fff; padding:24px 32px; border-radius:8px 8px 0 0;">
        <div style="font-size:12px; letter-spacing:1px; opacity:0.75;">VERIDIAN LIFE SCIENCES &middot; VERIDIAN CAMPAIGN STUDIO</div>
        <h1 style="margin:8px 0 0; font-size:24px;">Campaign Sprint</h1>
        <div style="font-size:13px; opacity:0.85; margin-top:4px;">Fictional demonstration &middot; Draft for human review</div>
      </div>
      <div style="background:#fff; padding:32px; border-radius:0 0 8px 8px; border:1px solid #E2E8EF; border-top:none;">

        <div id="staleBanner" style="display:none; background:#fdf1e6; border:1px solid #f0c98a; color:#A86408; padding:12px 16px; border-radius:6px; margin-bottom:20px; font-size:13px;">
          Content changed &mdash; recheck required. These results may be outdated &mdash; click "Recheck revised content" to update them.
        </div>

        ${eventSummaryHtml}

        <h2 style="color:#087F8C;">Content <span id="versionLabel" style="font-size:13px; font-weight:400; color:#5b6b76;"></span></h2>

        <h3>Email</h3>
        <label style="display:block; font-weight:600; margin-bottom:4px; font-size:13px;">Subject line</label>
        <input id="editEmailHeadline" type="text" value="${esc(campaign.email.headline)}" style="width:100%; padding:8px 10px; border:1px solid #d3e3ec; border-radius:6px; font-family:inherit; font-size:14px; margin-bottom:10px;">
        <label style="display:block; font-weight:600; margin-bottom:4px; font-size:13px;">Body</label>
        <textarea id="editEmailBody" rows="4" style="width:100%; padding:8px 10px; border:1px solid #d3e3ec; border-radius:6px; font-family:inherit; font-size:14px; margin-bottom:10px;">${esc(campaign.email.body)}</textarea>
        <label style="display:block; font-weight:600; margin-bottom:4px; font-size:13px;">Call to action</label>
        <input id="editEmailCta" type="text" value="${esc(campaign.email.cta)}" style="width:100%; padding:8px 10px; border:1px solid #d3e3ec; border-radius:6px; font-family:inherit; font-size:14px; margin-bottom:16px;">

        <hr style="border:none; border-top:1px solid #E2E8EF; margin:20px 0;">

        <h3>Landing page</h3>
        <label style="display:block; font-weight:600; margin-bottom:4px; font-size:13px;">Headline</label>
        <input id="editLandingHeadline" type="text" value="${esc(campaign.landing_page.headline)}" style="width:100%; padding:8px 10px; border:1px solid #d3e3ec; border-radius:6px; font-family:inherit; font-size:14px; margin-bottom:10px;">
        <label style="display:block; font-weight:600; margin-bottom:4px; font-size:13px;">Body</label>
        <textarea id="editLandingBody" rows="4" style="width:100%; padding:8px 10px; border:1px solid #d3e3ec; border-radius:6px; font-family:inherit; font-size:14px; margin-bottom:10px;">${esc(campaign.landing_page.body)}</textarea>
        <label style="display:block; font-weight:600; margin-bottom:4px; font-size:13px;">Call to action</label>
        <input id="editLandingCta" type="text" value="${esc(campaign.landing_page.cta)}" style="width:100%; padding:8px 10px; border:1px solid #d3e3ec; border-radius:6px; font-family:inherit; font-size:14px; margin-bottom:16px;">

        <p style="font-size:13px; color:#5b6b76;"><em>Creative rationale:</em> ${esc(campaign.creative_rationale)}</p>
        <p style="font-size:13px; color:#5b6b76;"><em>How your instruction was handled:</em> ${esc(campaign.instruction_response)}</p>

