const cd = $('Campaign Data').first().json;
const email = { headline: cd.email_headline, body: cd.email_body, cta: cd.email_cta };
const landing = { headline: cd.landing_headline, body: cd.landing_body, cta: cd.landing_cta };

const REQUIRED_DISCLOSURE = "No continuing education credits are offered.";
const REQUIRED_CTA = "View the agenda and register";
const WORD_LIMIT = 100;

function wordCount(text) {
  return (text || "").trim().split(/\s+/).filter(Boolean).length;
}

function checkDisclosure() {
  const emailHas = (email.body || "").includes(REQUIRED_DISCLOSURE);
  const landingHas = (landing.body || "").includes(REQUIRED_DISCLOSURE);
  if (emailHas && landingHas) {
    return { rule_id: "R1", status: "no_issue_detected", asset: "both",
      wording: REQUIRED_DISCLOSURE, explanation: "Required disclosure found in both assets.",
      source_reference: "S5", source_excerpt: "No continuing education credits are offered.",
      suggested_correction: "N/A", human_review_action: "Confirm placement is prominent enough for review." };
  }
  const missing = [];
  if (!emailHas) missing.push("email");
  if (!landingHas) missing.push("landing_page");
  return { rule_id: "R1", status: "issues_flagged", asset: missing.join(" and "),
    wording: "(disclosure not found)", explanation: `Required disclosure missing from: ${missing.join(", ")}.`,
    source_reference: "S5", source_excerpt: "No continuing education credits are offered.",
    suggested_correction: `Add the exact sentence "${REQUIRED_DISCLOSURE}" to: ${missing.join(", ")}.`,
    human_review_action: "Add missing disclosure before this asset is used." };
}

function checkCTA() {
  const bad = [];
  if ((email.cta || "").trim() !== REQUIRED_CTA) bad.push("email");
  if ((landing.cta || "").trim() !== REQUIRED_CTA) bad.push("landing_page");
  if (bad.length === 0) {
    return { rule_id: "R2", status: "no_issue_detected", asset: "both",
      wording: REQUIRED_CTA, explanation: "CTA matches the required wording exactly in both assets.",
      source_reference: "Campaign CTA requirement", source_excerpt: `Use the call to action: "${REQUIRED_CTA}"`,
      suggested_correction: "N/A", human_review_action: "None." };
  }
  return { rule_id: "R2", status: "issues_flagged", asset: bad.join(" and "),
    wording: bad.map(a => (a === "email" ? email.cta : landing.cta)).join(" / "),
    explanation: `CTA does not exactly match required wording in: ${bad.join(", ")}.`,
    source_reference: "Campaign CTA requirement", source_excerpt: `Use the call to action: "${REQUIRED_CTA}"`,
    suggested_correction: `Replace CTA with exactly "${REQUIRED_CTA}" in: ${bad.join(", ")}.`,
    human_review_action: "Correct CTA wording before use." };
}

function checkWordCount() {
  const emailCount = wordCount(email.body);
  const landingCount = wordCount(landing.body);
  const over = [];
  if (emailCount > WORD_LIMIT) over.push(`email (${emailCount} words)`);
  if (landingCount > WORD_LIMIT) over.push(`landing_page (${landingCount} words)`);
  if (over.length === 0) {
    return { rule_id: "R3", status: "no_issue_detected", asset: "both",
      wording: `email: ${emailCount} words, landing_page: ${landingCount} words`,
      explanation: "Both asset bodies are within the 100-word limit.",
      source_reference: "N/A (format rule)", source_excerpt: "N/A",
      suggested_correction: "N/A", human_review_action: "None." };
  }
  return { rule_id: "R3", status: "issues_flagged", asset: over.join(" and "),
    wording: over.join(", "), explanation: `Body exceeds the 100-word limit: ${over.join(", ")}.`,
    source_reference: "N/A (format rule)", source_excerpt: "N/A",
    suggested_correction: "Trim body copy to 100 words or fewer.",
    human_review_action: "Shorten copy before use." };
}

const webhookBody = ($('Webhook').first().json && $('Webhook').first().json.body) || {};
const isEventUpdate = webhookBody.mode === 'event_update';

function normalizeDateTime(s) {
  return (s || '')
    .toLowerCase()
    .replace(/\./g, '')
    .replace(/\b0(\d)\b/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

function checkDateTimeUpdated() {
  const newDate = webhookBody.new_event_date || '';
  const newTime = webhookBody.new_event_time || '';
  const bodies = normalizeDateTime([email.body, landing.body].join(' '));
  const foundDate = !newDate || bodies.includes(normalizeDateTime(newDate));
  const foundTime = !newTime || bodies.includes(normalizeDateTime(newTime));
  if (foundDate && foundTime) {
    return { rule_id: "DT1", status: "no_issue_detected", asset: "both",
      wording: `${newDate} ${newTime}`, explanation: "Updated date/time found in the revised copy.",
      source_reference: "Updated source pack", source_excerpt: `${newDate}, ${newTime}`,
      suggested_correction: "N/A", human_review_action: "None." };
  }
  return { rule_id: "DT1", status: "issues_flagged", asset: "both",
    wording: `${newDate} ${newTime}`, explanation: "Updated date/time not found in one or both revised assets.",
    source_reference: "Updated source pack", source_excerpt: `${newDate}, ${newTime}`,
    suggested_correction: "Manually update the date/time reference.",
    human_review_action: "Verify date/time appears correctly in both assets." };
}

function checkNoOldDateTime() {
  const sources = $('Sources').first().json;
  const oldDate = sources.event_date || '';
  const oldTime = sources.event_time || '';
  const newDate = webhookBody.new_event_date || '';
  const newTime = webhookBody.new_event_time || '';
  const dateChanged = normalizeDateTime(oldDate) !== normalizeDateTime(newDate);
  const timeChanged = normalizeDateTime(oldTime) !== normalizeDateTime(newTime);
  const bodies = normalizeDateTime([email.body, landing.body, email.headline, landing.headline].join(' '));
  const staleDate = dateChanged && oldDate && bodies.includes(normalizeDateTime(oldDate));
  const staleTime = timeChanged && oldTime && bodies.includes(normalizeDateTime(oldTime));
  if (!staleDate && !staleTime) {
    return { rule_id: "DT2", status: "no_issue_detected", asset: "both",
      wording: "N/A", explanation: "No superseded date/time details remain in the revised copy.",
      source_reference: "Previous event details", source_excerpt: `${oldDate}, ${oldTime}`,
      suggested_correction: "N/A", human_review_action: "None." };
  }
  const stale = [staleDate ? oldDate : null, staleTime ? oldTime : null].filter(Boolean).join(' / ');
  return { rule_id: "DT2", status: "issues_flagged", asset: "both",
    wording: stale, explanation: "Outdated date/time details were left in the revised copy.",
    source_reference: "Previous event details", source_excerpt: `${oldDate}, ${oldTime}`,
    suggested_correction: "Remove the outdated date/time reference.",
    human_review_action: "Manually remove leftover outdated date/time text." };
}

function checkUnrelatedUnchanged() {
  return { rule_id: "DT3", status: "not_assessable", asset: "both",
    wording: "N/A", explanation: "Automated wording-drift comparison is not performed by code for this check; review unrelated wording manually.",
    source_reference: "N/A", source_excerpt: "N/A",
    suggested_correction: "N/A", human_review_action: "Manually confirm no unrelated wording changed." };
}

const event_check_results = isEventUpdate ? [checkDateTimeUpdated(), checkNoOldDateTime(), checkUnrelatedUnchanged()] : [];

const code_check_results = [checkDisclosure(), checkCTA(), checkWordCount()];

return [{ json: { code_check_results, event_check_results } }];

