function tryParseJSON(x) {
  if (typeof x !== 'string') return x;
  try { return JSON.parse(x); } catch (e) { return null; }
}

function extractRuleResults(nodeName) {
  const raw = $(nodeName).first().json;
  const parsed = tryParseJSON(raw.output ?? raw.text ?? raw);
  return (parsed && Array.isArray(parsed.rule_results)) ? parsed.rule_results : [];
}

const run1 = extractRuleResults("Pre-MLR Check");
const run2 = extractRuleResults("Pre-MLR Check1");

const priority = { issues_flagged: 2, not_assessable: 1, no_issue_detected: 0 };

const byRule = {};
for (const r of run1) { byRule[r.rule_id] = r; }
for (const r of run2) {
  const existing = byRule[r.rule_id];
  if (!existing) {
    byRule[r.rule_id] = r;
  } else {
    const pExisting = priority[existing.status] ?? 0;
    const pNew = priority[r.status] ?? 0;
    if (pNew > pExisting) {
      byRule[r.rule_id] = r;
    }
  }
}

const rule_results = Object.values(byRule);

return [{ json: { rule_results } }];
